using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Xml;
using System.Xml.Linq;
using DocumentIDE.Core.Docx;
using DocumentIDE.Infrastructure.Docx;

namespace DocumentIDE.GoldenTests;

/// <summary>
/// QA-01 — Golden DOCX Regression Corpus.
/// Required tests: (1) all fixtures open/parse as expected, (2) strict
/// replacement invariant suite passes, (3) hostile fixtures fail safely.
/// Every fixture is generated byte-deterministically at test time.
/// </summary>
public class DocxGoldenTests : IDisposable
{
    private static readonly XNamespace W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";

    private readonly string _tempDirectory;
    private int _fileCounter;

    public DocxGoldenTests()
    {
        _tempDirectory = Path.Combine(Path.GetTempPath(), $"DocxGoldenTests_{Guid.NewGuid():N}");
        Directory.CreateDirectory(_tempDirectory);
    }

    public void Dispose()
    {
        if (Directory.Exists(_tempDirectory))
        {
            try { Directory.Delete(_tempDirectory, recursive: true); } catch { }
        }
    }

    public static IEnumerable<object[]> ValidFixtureNames() =>
        GoldenDocxFixtures.Valid.Select(f => new object[] { f.Name });

    public static IEnumerable<object[]> HostileFixtureNames() =>
        GoldenDocxFixtures.Hostile.Select(f => new object[] { f.Name });

    // ------------------------------------------------------------------
    // Required test 1: All fixtures open/parse as expected (mandated first).
    // ------------------------------------------------------------------

    [Fact]
    public void AllGoldenFixtures_OpenAndParseAsExpected()
    {
        var fixtures = GoldenDocxFixtures.Valid;
        Assert.NotEmpty(fixtures);

        foreach (var fixture in fixtures)
        {
            Assert.False(string.IsNullOrWhiteSpace(fixture.Purpose));

            // Acceptance: corpus is deterministic — identical bytes on every build.
            byte[] firstBuild = fixture.BuildPackage();
            byte[] secondBuild = fixture.BuildPackage();
            Assert.True(
                firstBuild.AsSpan().SequenceEqual(secondBuild),
                $"[{fixture.Name}] fixture generation is not byte-deterministic.");

            string path = WriteFixture(fixture.Name, firstBuild);

            // Package opens and passes preflight.
            var preflight = new DocxPackagePreflight();
            var validation = preflight.ValidatePackage(path);
            Assert.True(
                validation.IsValid,
                $"[{fixture.Name}] preflight failed: {validation.ErrorCode} — {validation.ErrorMessage}");
            Assert.True(
                validation.Warnings.Count == 0,
                $"[{fixture.Name}] valid fixture produced preflight warnings: {string.Join(" | ", validation.Warnings)}");

            using (var archive = ZipFile.OpenRead(path))
            {
                Assert.NotNull(archive.GetEntry("[Content_Types].xml"));
                Assert.NotNull(archive.GetEntry("_rels/.rels"));
                Assert.NotNull(archive.GetEntry("word/document.xml"));

                int headerParts = archive.Entries.Count(e =>
                    e.FullName.StartsWith("word/header", StringComparison.OrdinalIgnoreCase) &&
                    e.FullName.EndsWith(".xml", StringComparison.OrdinalIgnoreCase));
                int footerParts = archive.Entries.Count(e =>
                    e.FullName.StartsWith("word/footer", StringComparison.OrdinalIgnoreCase) &&
                    e.FullName.EndsWith(".xml", StringComparison.OrdinalIgnoreCase));

                Assert.True(
                    headerParts == fixture.ExpectedHeaderParts,
                    $"[{fixture.Name}] expected {fixture.ExpectedHeaderParts} header parts, found {headerParts}.");
                Assert.True(
                    footerParts == fixture.ExpectedFooterParts,
                    $"[{fixture.Name}] expected {fixture.ExpectedFooterParts} footer parts, found {footerParts}.");

                // Every XML/relationship part parses with safe reader settings.
                var xmlSettings = new XmlReaderSettings
                {
                    DtdProcessing = DtdProcessing.Prohibit,
                    XmlResolver = null
                };
                foreach (var entry in archive.Entries.Where(e =>
                             e.FullName.EndsWith(".xml", StringComparison.OrdinalIgnoreCase) ||
                             e.FullName.EndsWith(".rels", StringComparison.OrdinalIgnoreCase)))
                {
                    using var entryStream = entry.Open();
                    using var reader = XmlReader.Create(entryStream, xmlSettings);
                    while (reader.Read()) { }
                }

                // Expected structural counts in the main document part.
                var documentXml = LoadXmlPart(archive, "word/document.xml");
                Assert.True(
                    documentXml.Descendants(W + "tbl").Count() == fixture.ExpectedTables,
                    $"[{fixture.Name}] expected {fixture.ExpectedTables} tables, found {documentXml.Descendants(W + "tbl").Count()}.");
                Assert.True(
                    documentXml.Descendants(W + "sectPr").Count() == fixture.ExpectedSections,
                    $"[{fixture.Name}] expected {fixture.ExpectedSections} sections, found {documentXml.Descendants(W + "sectPr").Count()}.");
            }

            Assert.True(
                validation.Metrics.MediaCount == fixture.ExpectedMediaParts,
                $"[{fixture.Name}] expected {fixture.ExpectedMediaParts} media parts, found {validation.Metrics.MediaCount}.");

            // Expected logical text is found with the expected structural origin.
            var matcher = new LogicalTextMatcher(new DocxPackagePreflight());
            foreach (var (text, origin) in fixture.ExpectedTexts)
            {
                var matches = matcher.Search(path, text);
                Assert.True(
                    matches.Count > 0,
                    $"[{fixture.Name}] expected logical text '{text}' was not found.");
                Assert.True(
                    matches.Any(m => m.Origin == origin),
                    $"[{fixture.Name}] expected '{text}' to be found at origin {origin}; " +
                    $"actual origins: {string.Join(", ", matches.Select(m => m.Origin).Distinct())}.");
            }

            // Text that must stay invisible to matching (deleted revisions, field codes, ...).
            foreach (string absent in fixture.AbsentTexts)
            {
                Assert.True(
                    matcher.Search(path, absent).Count == 0,
                    $"[{fixture.Name}] logical text '{absent}' must not be searchable.");
            }
        }
    }

    // ------------------------------------------------------------------
    // Required test 3: Hostile fixtures fail safely.
    // ------------------------------------------------------------------

    [Theory]
    [MemberData(nameof(HostileFixtureNames))]
    public void HostileFixtures_FailSafely(string fixtureName)
    {
        var fixture = GoldenDocxFixtures.Hostile.Single(f => f.Name == fixtureName);
        Assert.False(string.IsNullOrWhiteSpace(fixture.Purpose));
        byte[] bytes = fixture.BuildPackage();
        string path = WriteFixture(fixtureName, bytes);
        byte[] sourceBefore = File.ReadAllBytes(path);

        var preflight = new DocxPackagePreflight();

        if (fixture.FailureMode == HostileFailureMode.PreflightRejection)
        {
            var result = preflight.ValidatePackage(path, fixture.PreflightOptions);
            Assert.False(
                result.IsValid,
                $"[{fixture.Name}] hostile package must be rejected by preflight.");
            Assert.Equal(fixture.ExpectedPreflightError, result.ErrorCode);
            Assert.True(
                result.Status == DocxPreflightStatus.SkippedForSafety || result.Status == DocxPreflightStatus.Corrupted,
                $"[{fixture.Name}] expected a safe preflight status, got {result.Status}.");
            Assert.False(string.IsNullOrWhiteSpace(result.ErrorMessage));

            // The deep mutation path must be blocked before any package rewrite.
            var mutator = new StrictTextMutator(preflight);
            Assert.Throws<InvalidOperationException>(() => mutator.MutateText(path, "GOLDEN", "ARCHIVE"));
        }
        else
        {
            // Structurally acceptable, but deep parsing must stay bounded by the occurrence budget.
            var result = preflight.ValidatePackage(path, fixture.PreflightOptions);
            Assert.True(
                result.IsValid,
                $"[{fixture.Name}] fixture is expected to pass preflight: {result.ErrorCode} — {result.ErrorMessage}");

            var matcher = new LogicalTextMatcher(preflight);
            var exception = Assert.Throws<InvalidDataException>(() =>
                matcher.Search(path, fixture.SearchTarget!, new DocxSearchOptions { MaxMatches = fixture.SearchBudget }));
            Assert.Equal("OccurrenceBudgetExceeded", exception.Message);
        }

        // In every hostile case the source file is byte-identical afterwards.
        Assert.True(
            sourceBefore.AsSpan().SequenceEqual(File.ReadAllBytes(path)),
            $"[{fixture.Name}] hostile handling must never modify the source file.");
    }

    [Fact]
    public void HighlyCompressedFixture_IsActuallyHighlyCompressed_AndStillBounded()
    {
        var fixture = GoldenDocxFixtures.Hostile.Single(f => f.Name == "hostile-high-compression");
        string path = WriteFixture(fixture.Name, fixture.BuildPackage());

        var result = new DocxPackagePreflight().ValidatePackage(path);

        Assert.True(result.IsValid);
        Assert.True(
            result.Metrics.TotalUncompressedSizeBytes >= 1_000_000,
            $"expected >= 1,000,000 uncompressed bytes, got {result.Metrics.TotalUncompressedSizeBytes}");
        Assert.True(
            result.Metrics.CompressedSizeBytes * 10 < result.Metrics.TotalUncompressedSizeBytes,
            $"fixture is not highly compressed: {result.Metrics.CompressedSizeBytes} -> {result.Metrics.TotalUncompressedSizeBytes}");
    }

    // ------------------------------------------------------------------
    // Required test 2: Strict replacement invariant suite passes.
    // ------------------------------------------------------------------

    public static IEnumerable<object[]> StrictReplacementFixtureNames() =>
        GoldenDocxFixtures.Valid.Select(f => new object[] { f.Name });

    [Theory]
    [MemberData(nameof(StrictReplacementFixtureNames))]
    public void StrictReplacement_InvariantSuite_Passes(string fixtureName)
    {
        var fixture = GoldenDocxFixtures.Valid.Single(f => f.Name == fixtureName);
        var replacementCase = fixture.StrictReplacement;

        string path = WriteFixture(fixtureName, fixture.BuildPackage());
        var beforeParts = GoldenDocxAssertions.ReadAllParts(path);
        string fingerprintBefore = GoldenDocxAssertions.Sha256Hex(path);

        var matcher = new LogicalTextMatcher(new DocxPackagePreflight());
        var targetMatchesBefore = matcher.Search(path, replacementCase.Target);
        Assert.Equal(replacementCase.ExpectedCount, targetMatchesBefore.Count);
        var changedParts = targetMatchesBefore
            .Select(m => m.PartName)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

        var mutator = new StrictTextMutator(new DocxPackagePreflight());
        var result = mutator.MutateText(path, replacementCase.Target, replacementCase.Replacement, new StrictMutationOptions
        {
            CreateRecoverySnapshot = false
        });

        // Requested property changed, and the package still opens after the change.
        Assert.True(result.Success, $"[{fixture.Name}] mutation failed: {result.ErrorMessage}");
        Assert.Equal(replacementCase.ExpectedCount, result.ReplacementsApplied);
        Assert.NotEqual(fingerprintBefore, GoldenDocxAssertions.Sha256Hex(path));
        GoldenDocxAssertions.AssertValidPackage(path);

        Assert.Empty(matcher.Search(path, replacementCase.Target));
        Assert.Equal(replacementCase.ExpectedCount, matcher.Search(path, replacementCase.Replacement).Count);

        // Unrelated properties and content: other parts, other paragraphs,
        // structural/formatting elements and uninvolved run formatting unchanged.
        GoldenDocxAssertions.AssertPartsUnchanged(beforeParts, path, changedParts);

        foreach (string partName in changedParts)
        {
            byte[] beforePart = beforeParts[partName];
            byte[] afterPart = GoldenDocxAssertions.ReadPart(path, partName);

            var matchedParagraphs = GoldenDocxAssertions.FindParagraphIndicesContaining(beforePart, replacementCase.Target);
            Assert.NotEmpty(matchedParagraphs);

            GoldenDocxAssertions.AssertOnlyMatchedParagraphsChanged(beforePart, afterPart, matchedParagraphs, partName);
            GoldenDocxAssertions.AssertInvariantElementsUnchanged(beforePart, afterPart, partName);

            foreach (int paragraphIndex in matchedParagraphs)
            {
                GoldenDocxAssertions.AssertRunFormattingPreserved(
                    beforePart, afterPart, paragraphIndex, replacementCase.Target, replacementCase.Replacement, partName);
            }
        }
    }

    // ------------------------------------------------------------------
    // No-op fingerprint tests (spec 06 §19: no-op must not rewrite bytes)
    // ------------------------------------------------------------------

    [Theory]
    [MemberData(nameof(ValidFixtureNames))]
    public void NoOpIndexing_DoesNotModifyPackageBytes(string fixtureName)
    {
        var fixture = GoldenDocxFixtures.Valid.Single(f => f.Name == fixtureName);
        string path = WriteFixture(fixtureName, fixture.BuildPackage());
        byte[] before = File.ReadAllBytes(path);

        var preflight = new DocxPackagePreflight();
        Assert.True(preflight.ValidatePackage(path).IsValid);

        var matcher = new LogicalTextMatcher(preflight);
        foreach (var (text, _) in fixture.ExpectedTexts)
        {
            matcher.Search(path, text);
        }

        Assert.True(
            before.AsSpan().SequenceEqual(File.ReadAllBytes(path)),
            $"[{fixture.Name}] indexing (preflight + search) must not modify the source package.");
    }

    [Fact]
    public void NoOpMutation_TargetAbsent_DoesNotModifyPackageBytes()
    {
        string path = WriteFixture("noop-target-absent", GoldenDocxFixtureBuilder.SplitRuns());
        byte[] before = File.ReadAllBytes(path);

        var mutator = new StrictTextMutator(new DocxPackagePreflight());
        var result = mutator.MutateText(path, "ABSENT-TOKEN-XYZ", "anything", new StrictMutationOptions
        {
            CreateRecoverySnapshot = false
        });

        Assert.True(result.Success);
        Assert.Equal(0, result.ReplacementsApplied);
        Assert.True(
            before.AsSpan().SequenceEqual(File.ReadAllBytes(path)),
            "A mutation whose target does not occur must not rewrite the package bytes (spec 06 §19).");
    }

    [Fact]
    public void NoOpMutation_IdentityReplacement_DoesNotModifyPackageBytes()
    {
        string path = WriteFixture("noop-identity", GoldenDocxFixtureBuilder.SplitRuns());
        byte[] before = File.ReadAllBytes(path);

        var mutator = new StrictTextMutator(new DocxPackagePreflight());
        var result = mutator.MutateText(path, "NUSA-DUA-1", "NUSA-DUA-1", new StrictMutationOptions
        {
            CreateRecoverySnapshot = false
        });

        Assert.True(result.Success);
        Assert.Equal(0, result.ReplacementsApplied);
        Assert.True(
            before.AsSpan().SequenceEqual(File.ReadAllBytes(path)),
            "An identity replacement must not rewrite the package bytes (spec 06 §19).");
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private string WriteFixture(string fixtureName, byte[] bytes)
    {
        string path = Path.Combine(_tempDirectory, $"{fixtureName}_{++_fileCounter}.docx");
        File.WriteAllBytes(path, bytes);
        return path;
    }

    internal static XDocument LoadXmlPart(ZipArchive archive, string partName)
    {
        var entry = archive.GetEntry(partName)
            ?? throw new InvalidOperationException($"Part '{partName}' is missing.");
        using var stream = entry.Open();
        using var reader = XmlReader.Create(stream, new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,
            XmlResolver = null
        });
        return XDocument.Load(reader);
    }
}
